import re,json,html
t=open('products/research/cantina-bounties-20261115.html','rb').read().decode('utf-8','replace')
parts=re.findall(r'self\.__next_f\.push\(\[1,"(.*?)"\]\)</script>',t,flags=re.S)
s=''
for p in parts:
    try: s+=json.loads('"'+p+'"')
    except Exception: s+=p
def clean(x): return re.sub(r'\s+',' ',html.unescape(re.sub(r'<[^>]+>',' ',x)))
# chunk markers like '69:T19363,'
mk=[(m.start(),m.group(0)) for m in re.finditer(r'(?:^|\n)[0-9a-f]{1,3}:T[0-9a-f]+,',s)]
print('markers',len(mk))
for a,(pos,g) in enumerate(mk):
    end=mk[a+1][0] if a+1<len(mk) else len(s)
    seg=s[pos:end]
    c=seg.count('Coinbase')
    print(pos,g.strip(),end-pos,'cb',c,'|',clean(seg[len(g):len(g)+110]))
for kw in ['KYC','AI ','LLM','automated','agent','submission fee','eposit','HackerOne','sanction','identity']:
    for m in re.finditer(kw,s):
        i=m.start()
        if 60000<i<200000:
            print('\n##',kw,i,clean(s[max(0,i-250):i+350]))
